"use strict";(globalThis.webpackChunkgrc||=[]).push([[15672],{38032(e){e.exports=JSON.parse('{"citeKey":"liu2019lpm","slug":"liu-2019-lpm-e1f4","title":"LPM: A Systematic Methodology for Concurrent Data Access Pattern Optimization from a Matching Perspective","authors":["Y. Liu","X.-H. Sun"],"venue":"IEEE Transactions on Parallel and Distributed Systems (TPDS), 2019. vol 30. no 11. pp.2478-2493.","type":"Journal","entryType":"article","date":"November, 2019","year":2019,"era":"iit","month":11,"doi":"10.1109/tpds.2019.2912573","abstract":"As applications become increasingly data intensive, conventional computing systems become increasingly inefficient due to data access performance bottlenecks. While intensive efforts have been made in developing new memory technologies and in designing special purpose machines, there is a lack of solutions for evaluating and utilizing recent hardware advancements to address the memory-wall problem in a systematic way. In this study, we present the memory Layered Performance Matching (LPM) methodology to provide a systematic approach for data access performance optimization. LPM uniquely presents and utilizes the data access concurrency, in addition to data access locality, in a memory hierarchical system. The LPM methodology consists of models and algorithms, and is supported with a series of analytic results for its correctness. The rationale of LPM is to reduce the overall data access delay through the matching of data request rate and data supply rate at each layer of a memory hierarchy, with a balanced consideration of data locality, data concurrency, and latency hiding of data flow. Extensive experimentations on both physical platforms and software simulators confirm our theoretical findings, and they show that the LPM approach can be applied in diverse computing platforms and can effectively guide performance optimization of memory systems.","hasAbstract":true,"lede":"In this study, we present the memory Layered Performance Matching (LPM) methodology to provide a systematic approach for data access performance optimization.","links":{"pdf":"https://grc.iit.edu/papers/2019/liu-2019-lpm-e1f4.pdf","slides":"https://grc.iit.edu/papers/2019/liu-2019-lpm-e1f4-slides.pdf"},"tags":["Memory-Wall","Memory Stall Time","Efficiency","Performance Optimization","Layered Performance Matching (LPM)","Memory Concurrency"],"_projectIds":["memory-parallelism","dep","push-io"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["memory-parallelism","dep","push-io"],"memberAuthors":["sun-xian-he"],"funding":[{"agency":"NSF","award":"CCF-1536079","projectId":"memory-parallelism"},{"agency":"NSF","award":"CNS-1162540","projectId":"dep"},{"agency":"NSF","award":"CCF-0937877","projectId":"push-io"}]}')}}]);